<!doctype html>
<html lang="es">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>{{ $company->name }} · Tienda</title>
    <style>
        :root{--ink:#17212b;--muted:#687789;--brand:#1769aa;--navy:#0d1b2a;--line:#dce5ed;--soft:#f6f9fc;--green:#087d56}*{box-sizing:border-box}body{margin:0;background:var(--soft);color:var(--ink);font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.notice{background:#fff3cd;color:#805b00;text-align:center;padding:9px 18px;font-size:13px;font-weight:650}.header{background:white;border-bottom:1px solid var(--line);position:sticky;top:0;z-index:5}.bar{max-width:1200px;margin:auto;padding:17px 24px;display:flex;align-items:center;justify-content:space-between;gap:20px}.brand{font-size:21px;font-weight:850;letter-spacing:-.6px}.brand small{display:block;color:var(--muted);font-size:12px;font-weight:600;letter-spacing:0}.cart{border:1px solid #b9d5e9;border-radius:9px;background:#eff8ff;color:#115784;padding:9px 12px;font:inherit;font-weight:750;cursor:pointer}.hero{background:linear-gradient(120deg,#0d1b2a,#164b77);color:#fff}.hero-inner{max-width:1200px;margin:auto;padding:56px 24px 64px}.hero h1{font-size:clamp(30px,5vw,50px);letter-spacing:-1.6px;margin:0 0 10px}.hero p{color:#d1e5f5;max-width:630px;line-height:1.6;margin:0}.hero a{display:inline-block;margin-top:21px;border:1px solid #7bc4f3;border-radius:8px;color:#fff;padding:9px 12px;text-decoration:none;font-size:13px}.content{max-width:1200px;margin:0 auto;padding:36px 24px 70px}.section-head{display:flex;justify-content:space-between;align-items:end;gap:20px;margin-bottom:20px}.section-head h2{margin:0;font-size:24px;letter-spacing:-.5px}.section-head p{margin:4px 0 0;color:var(--muted);font-size:14px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:17px}.product{background:white;border:1px solid var(--line);border-radius:14px;overflow:hidden;display:flex;flex-direction:column}.visual{height:132px;background:linear-gradient(135deg,#dfeffc,#c8e2f8);display:grid;place-items:center;color:#3778a7;font-size:36px}.details{padding:15px;display:flex;flex:1;flex-direction:column}.sku{font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.08em}.product h3{font-size:16px;margin:6px 0}.description{font-size:13px;line-height:1.45;color:var(--muted);min-height:38px;margin:0}.bottom{margin-top:auto;padding-top:16px;display:flex;align-items:center;justify-content:space-between;gap:8px}.price{font-size:17px;font-weight:850}.add{border:0;border-radius:7px;background:var(--brand);color:#fff;padding:8px 10px;font:inherit;font-size:13px;font-weight:750;cursor:pointer}.add:hover{background:#0e578e}.empty{background:white;border:1px dashed #b7c9da;border-radius:14px;padding:48px 28px;text-align:center}.empty h3{margin:0 0 8px}.empty p{margin:0;color:var(--muted)}.drawer{position:fixed;right:20px;bottom:20px;width:min(370px,calc(100% - 40px));background:#fff;border:1px solid var(--line);border-radius:15px;box-shadow:0 20px 50px rgba(15,38,61,.2);padding:18px;z-index:7;display:none}.drawer.open{display:block}.drawer h3{margin:0 0 12px}.items{max-height:250px;overflow:auto}.line{display:flex;justify-content:space-between;border-top:1px solid #edf1f5;padding:10px 0;font-size:14px}.checkout{border:0;background:var(--green);color:white;width:100%;padding:10px;border-radius:8px;font-weight:800;margin-top:12px;cursor:pointer}.foot{border-top:1px solid var(--line);background:white;color:var(--muted);padding:24px;text-align:center;font-size:13px}@media(max-width:900px){.grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:520px){.grid{grid-template-columns:1fr}.hero-inner{padding:40px 24px}.section-head{align-items:start;flex-direction:column}.bar{padding:14px 17px}.content{padding:28px 17px}}
    </style>
</head>
<body>
    @if($preview)<div class="notice">Vista previa local de la tienda. El dominio público se configura desde Administración.</div>@endif
    <header class="header"><div class="bar"><div class="brand">{{ $company->name }}<small>{{ $storefront?->domain ?: 'Tienda e-commerce' }}</small></div><button class="cart" type="button" onclick="toggleCart()">🛒 Carrito <span id="cart-count">0</span></button></div></header>
    <section class="hero"><div class="hero-inner"><h1>Compra fácil, rápido y seguro.</h1><p>Catálogo publicado para {{ $company->name }}. El pedido se valida en el POS antes de generar una venta.</p>@if($preview)<a href="{{ request()->fullUrlWithQuery(['sync' => 1]) }}">Actualizar catálogo desde POS</a>@endif</div></section>
    <main class="content"><div class="section-head"><div><h2>Productos destacados</h2><p>{{ $products->count() }} productos publicados para esta compañía.</p></div></div>
        @if($products->isEmpty())<section class="empty"><h3>El catálogo está listo para sincronizarse</h3><p>Aún no hay productos publicados. Activa la sincronización desde POS para verlos aquí.</p></section>@else
        <section class="grid">@foreach($products as $product)<article class="product"><div class="visual">{{ $product->image_url ? '▣' : '◈' }}</div><div class="details"><span class="sku">{{ $product->sku ?: 'Producto' }}</span><h3>{{ $product->name }}</h3><p class="description">{{ $product->description ?: 'Producto disponible en la tienda.' }}</p><div class="bottom"><span class="price">{{ $product->currency }} {{ number_format((float) $product->price, 2, ',', '.') }}</span><button class="add" type="button" data-name="{{ e($product->name) }}" data-price="{{ $product->price }}" onclick="addToCart(this)">Agregar</button></div></div></article>@endforeach</section>@endif
    </main>
    <aside id="cart-drawer" class="drawer"><h3>Tu carrito</h3><div id="cart-items" class="items"><p style="color:#687789">Aún no agregas productos.</p></div><button class="checkout" type="button" onclick="alert('La vista de checkout se conectará al endpoint seguro del POS.')">Continuar al pago</button></aside>
    <footer class="foot">{{ $company->name }} · Tienda operada por Saturnext</footer>
    <script>
        const cart=[];function toggleCart(){document.getElementById('cart-drawer').classList.toggle('open')}function addToCart(button){cart.push({name:button.dataset.name,price:Number(button.dataset.price)});document.getElementById('cart-count').textContent=cart.length;document.getElementById('cart-items').innerHTML=cart.map(item=>`<div class="line"><span>${item.name}</span><strong>${item.price.toLocaleString('es-CO')}</strong></div>`).join('');document.getElementById('cart-drawer').classList.add('open')}
    </script>
</body>
</html>
